// Extract Due Diligence tasks and prepare for database
const tasks = $input.first().json.result || [];
console.log(`Found ${tasks.length} total tasks`);

const dueDiligenceTasks = [];

for (const task of tasks) {
  const title = task.title ? task.title.toString().trim() : '';
  const description = task.description ? task.description.toString().trim() : '';

  // Check if title contains "Due Diligence" (case insensitive)
  const titleLower = title.toLowerCase();
  if (titleLower.includes('due diligence')) {
    let companyName = '';

    // Extract company name from title
    const colonPattern = /due diligence:\s*(.+)/i;
    const colonMatch = title.match(colonPattern);
    if (colonMatch) {
      companyName = colonMatch[1].trim().replace(/^["']+|["']+$/g, '');
    } else {
      const afterDD = title.substring(title.toLowerCase().indexOf('due diligence') + 13).trim();
      companyName = afterDD.replace(/^[:\s"']+/, '').replace(/["']+$/, '').trim() || 'Unknown Company';
    }

    // Extract website from description
    const urlRegex = /https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)/g;
    const urls = description.match(urlRegex) || [];
    const website = urls.length > 0 ? urls[0] : '';

    console.log(`✅ Found Due Diligence task: "${companyName}" (ID: ${task.id})`);

    dueDiligenceTasks.push({
      json: {
        task_id: parseInt(task.id),
        kanboard_task_id: parseInt(task.id),
        title: title,
        company_name: companyName,
        website: website,
        description: description,
        project_id: task.project_id || 1,
        status: 'pending',
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString()
      }
    });
  }
}

if (dueDiligenceTasks.length === 0) {
  console.log('ℹ️ No Due Diligence tasks found');
  // Return empty result to stop the workflow gracefully
  return [];
}

console.log(`📋 Processing ${dueDiligenceTasks.length} Due Diligence tasks`);
return dueDiligenceTasks;

