// Check what we received from the Get Task Files node
const taskData = $('Find Due Diligence Task').first().json;
const files = $input.first().json.result || [];

if (files.length === 0) {
  console.log('ℹ️ No files found attached to this task, proceeding without attachments');
  return [{
    json: {
      ...taskData,
      has_attachments: false,
      attachment_text: '',
      skip_download: true
    }
  }];
}

// Log the file information for debugging
console.log('Files found:', JSON.stringify(files, null, 2));

// Get the first PDF file
const pdfFile = files.find(file => 
  file.name && file.name.toLowerCase().endsWith('.pdf')
) || files[0];

console.log(`📎 Processing file: ${pdfFile.name} (ID: ${pdfFile.id})`);

// Return the file ID and name along with the original task data
return [{
  json: {
    ...taskData,
    file_id: pdfFile.id,
    file_name: pdfFile.name,
    file_path: pdfFile.path,
    has_attachments: true,
    skip_download: false
  }
}];

// CRITICAL FIX: Move binary data to the 'data' property
// The extractFromFile node specifically looks for binary data in a property called 'data'

const items = $input.all();
const processedItems = [];

for (const item of items) {
  const newItem = {
    json: item.json,
    binary: {}
  };

  // Check if we have binary data
  if (item.binary && Object.keys(item.binary).length > 0) {
    // Find the first binary property (usually 'data' from HTTP Request)
    const binaryKey = Object.keys(item.binary)[0];
    const binaryData = item.binary[binaryKey];

    console.log(`📋 Found binary data with key: ${binaryKey}`);
    console.log(`📋 Binary data info:`, {
      mimeType: binaryData.mimeType,
      fileExtension: binaryData.fileExtension,
      fileName: binaryData.fileName
    });

    // Move binary data to the 'data' property that extractFromFile expects
    newItem.binary.data = {
      data: binaryData.data,
      mimeType: binaryData.mimeType || 'application/pdf',
      fileExtension: binaryData.fileExtension || 'pdf',
      fileName: binaryData.fileName || item.json.file_name || 'document.pdf'
    };

    console.log(`✅ Moved binary data to 'data' property for extractFromFile`);
  } else {
    console.log('⚠️ No binary data found in item');
  }

  processedItems.push(newItem);
}

return processedItems;

// Combine extracted text with task data
const taskData = $('Has Files?').first().json;
const extractedData = $input.first().json;

const attachmentText = extractedData.data || extractedData.text || '';

console.log(`📄 Extracted ${attachmentText.length} characters from PDF`);

return [{
  json: {
    ...taskData,
    attachment_text: attachmentText,
    extracted_successfully: true
  }
}];

// Handle both paths - with and without attachments
const allItems = $input.all();
console.log(`📋 Merge received ${allItems.length} items`);

// Find the item with the most complete data
let bestItem = null;
for (const item of allItems) {
  console.log(`📋 Item data:`, {
    kanboard_task_id: item.json.kanboard_task_id,
    company_name: item.json.company_name,
    has_attachments: item.json.has_attachments,
    extracted_successfully: item.json.extracted_successfully
  });

  if (item.json.kanboard_task_id && item.json.company_name) {
    bestItem = item;
    break;
  }
}

if (!bestItem) {
  console.error('❌ No valid item found with required data');
  throw new Error('No valid task data found');
}

const finalData = bestItem.json;

// Ensure required fields exist
if (!finalData.kanboard_task_id) {
  console.error('❌ Missing kanboard_task_id:', finalData);
  throw new Error('kanboard_task_id is required but missing');
}

if (finalData.has_attachments && finalData.extracted_successfully) {
  console.log(`📄 Task with PDF attachment processed: ${finalData.company_name}`);
} else if (!finalData.has_attachments) {
  console.log(`📋 Task without attachments processed: ${finalData.company_name}`);
} else {
  console.log(`⚠️ Task with attachment but extraction failed: ${finalData.company_name}`);
}

return [{ json: finalData }];

