// Check which sections are missing for the report
const reports = $input.all();

if (reports.length === 0) {
  return [{ json: { message: 'No in-progress reports found', skip: true } }];
}

const report = reports[0].json;

// Define all 20 due diligence sections in order
const ddSections = [
  'introduction_engagement_context',
  'methodology_reliability_levels', 
  'company_overview',
  'business_model_unit_economics',
  'products_technology',
  'target_market_competitive_set',
  'financials_multi_year',
  'cash_burn_runway',
  'revenue_quality_client_cohorts',
  'partnerships_ecosystem',
  'intellectual_property',
  'legal_regulatory',
  'governance_board_effectiveness',
  'capital_structure_dilution',
  'risk_matrix_mitigations',
  'gaps_uncertainties_disclaimers',
  'scenario_analysis',
  'strategic_options',
  'recommendations_next_steps',
  'source_map_integrity_log'
];

// Find the first missing section
for (const section of ddSections) {
  if (!report[section] || report[section].trim() === '') {
    const sectionTitle = section.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());

    console.log(`📝 Generating section: ${sectionTitle}`);

    return [{
      json: {
        id: report.id,
        kanboard_task_id: report.kanboard_task_id,
        company_name: report.company_name,
        website: report.website,
        description: report.description,
        attachment_text: report.attachment_info || '',
        section_name: section,
        section_title: sectionTitle,
        existing_sections: ddSections.filter(s => report[s] && report[s].trim() !== '').map(s => s.replace(/_/g, ' ')).join(', ')
      }
    }];
  }
}

// All sections are complete
console.log(`✅ All sections complete for ${report.company_name}`);
return [{ json: { message: 'All sections complete', skip: true, report_id: report.id } }];

// Process AI response and prepare for database update
const sectionData = $('Has Work to Do?').first().json;
const aiResponse = $input.first().json;

const generatedContent = aiResponse.response || '';
const cleanContent = generatedContent.trim();

console.log(`📝 Generated ${sectionData.section_title}: ${cleanContent.substring(0, 100)}...`);

return [{
  json: {
    id: sectionData.id,
    section_name: sectionData.section_name,
    section_content: cleanContent,
    updated_at: new Date().toISOString()
  }
}];
